 45	  return <div className="scout-manifest">
 46	    <div><h3>{manifest.name}</h3><p className="candidate-role">Approved manifest</p></div>
 47	    <dl className="scout-facts"><div><dt>Revision</dt><dd>{manifest.revision ?? 'Source default'}</dd></div><div><dt>Licence</dt><dd>{manifest.licenseId}</dd></div><div><dt>Evidence records</dt><dd>{manifest.evidenceIds.length}</dd></div><div><dt>Approved</dt><dd>{new Date(manifest.approvedAt).toLocaleString()}</dd></div></dl>
 48	    {manifest.limitations.length > 0 && <div><strong>Known limitations</strong><ul>{manifest.limitations.map(item => <li key={item}>{item}</li>)}</ul></div>}
 49	    <button className="btn btn-primary" onClick={onUseSource}>Open approved sources</button>
 50	  </div>;
 51	}
 52	
 53	export default function ScoutReview({ run, busy, onReview, onUseSource }: Props) {
 54	  const excludedCandidateIds = new Set(run.excludedCandidateIds);
 55	  const eligible = run.assessments.filter(item =>
 56	    candidateIsEligibleForApproval(item, excludedCandidateIds));
 57	  const approvedIds = new Set(approvedCandidateIds(run));
 58	  const remainingEligible = eligible.filter(item => !approvedIds.has(item.candidateId));
 59	  const isAdditionalApproval = run.status === 'APPROVED';
 60	  const approvalOptions = isAdditionalApproval ? remainingEligible : eligible;
 61	  const eligibleKey = approvalOptions.map(item => item.candidateId).join('|');
 62	  const defaultCandidateId = approvalOptions[0]?.candidateId
 63	    ?? run.approvedCandidateId ?? run.recommendedCandidateId ?? eligible[0]?.candidateId ?? '';
 64	  const [selectedCandidateId, setSelectedCandidateId] = useState(defaultCandidateId);
 65	  const [feedback, setFeedback] = useState('');
 66	  useEffect(() => {
 67	    setSelectedCandidateId(current => eligible.some(item => item.candidateId === current)
 68	      ? current : defaultCandidateId);
 69	    setFeedback('');
 70	  }, [defaultCandidateId, eligibleKey, run.reviewIterationsUsed]);
 71	  const candidate = run.candidates.find(item => item.id === selectedCandidateId);
 72	  const profile = run.profiles.find(item => item.candidateId === selectedCandidateId);
 73	  const assessment = run.assessments.find(item => item.candidateId === selectedCandidateId);
 74	  const mandatoryGaps = run.requirements.filter(item => item.priority === 'MUST' && item.status !== 'VERIFIED');
 75	  const hasRefinementSlot = run.reviewIterationsUsed < 2;
 76	  const hasRefinementCredits = run.tavilyCreditsUsed + 2 <= 12;
 77	  const refinementAvailable = run.feedbackAllowed
 78	    ?? (run.status === 'AWAITING_APPROVAL' && hasRefinementSlot && hasRefinementCredits);
 79	  const needsInput = run.status === 'NEEDS_INPUT';
 80	  const showReviewPanel = run.status === 'AWAITING_APPROVAL'
 81	    || (needsInput && refinementAvailable)
 82	    || (isAdditionalApproval && remainingEligible.length > 0);
 83	  const normalizedFeedback = feedback.trim();
 84	  const selectedApprovalCandidateId = approvalOptions.some(
 85	    item => item.candidateId === selectedCandidateId,
 86	  ) ? selectedCandidateId : approvalOptions[0]?.candidateId ?? '';
 87	
 88	  return <div className="scout-review" aria-live="polite">
 89	    <div className="scout-run-line"><span className={`run-status status-${run.status.toLowerCase()}`}>{run.status.replaceAll('_', ' ')}</span><span>mode: {run.executionMode.toLowerCase()} · {run.tavilyCreditsUsed}/12 Tavily credits · {run.gapQueriesUsed}/2 gap searches</span><span className="mono">{run.runId}</span></div>
 90	    {run.errors.length > 0 && <details className="scout-errors" open={run.status === 'FAILED'}><summary>Source coverage notes ({run.errors.length})</summary><ul>{run.errors.map(error => <li role={run.status === 'FAILED' ? 'alert' : undefined} key={error}>{friendlyRetrievalNote(error, run)}</li>)}</ul></details>}
 91	    {mandatoryGaps.length > 0 && <div className="scout-warning"><AlertTriangle size={15} aria-hidden="true" /><div><strong>{needsInput ? 'Recommendation withheld' : 'Mandatory evidence gaps'}</strong><ul>{mandatoryGaps.map(gap => <li key={gap.id}>{gap.label} — {gap.status.toLowerCase()}</li>)}</ul>{needsInput && !refinementAvailable && <p>No refinement budget remains. Start a new run after adjusting the brief or requirements.</p>}</div></div>}
 92	    {candidate && assessment && <CandidateSummary candidate={candidate} profile={profile} assessment={assessment} isRecommendation={selectedCandidateId === run.recommendedCandidateId} />}
 93	    {run.assessments.length > 0 && <DecisionEvidence run={run} candidateId={selectedCandidateId || undefined} />}
 94	    {showReviewPanel && <section className="scout-approval" aria-labelledby="scout-approval-title">
 95	      <div><strong id="scout-approval-title">{needsInput ? 'Help the scout continue' : isAdditionalApproval ? 'Approve another dataset' : 'Human decision required'}</strong><p>{needsInput ? 'No dataset passed the current contract. Direct the next bounded search with specific missing evidence, source types, or alternatives.' : isAdditionalApproval ? `${approvedIds.size} eligible dataset${approvedIds.size === 1 ? '' : 's'} approved from this run. Review and approve another candidate, or open the approved-source library when you are done.` : 'Approve any eligible dataset, or give the scout specific feedback for another bounded search.'}</p></div>
 96	      <div className={`scout-approval-grid${needsInput ? ' needs-input' : isAdditionalApproval ? ' additional-approval' : ''}`}>
 97	        {!needsInput && <div className="scout-approval-choice">
 98	          <label htmlFor={`approval-candidate-${run.runId}`}>Dataset to approve</label>
 99	          <select id={`approval-candidate-${run.runId}`} value={selectedApprovalCandidateId} onChange={event => setSelectedCandidateId(event.target.value)} disabled={Boolean(busy) || approvalOptions.length === 0}>
100	            {approvalOptions.length === 0 && <option value="">No eligible datasets</option>}
101	            {approvalOptions.map(item => <option key={item.candidateId} value={item.candidateId}>{run.candidates.find(candidateItem => candidateItem.id === item.candidateId)?.name ?? item.candidateId} — {candidateSuitabilityLabel(item)}{item.candidateId === run.recommendedCandidateId ? ' (agent recommendation)' : ''}</option>)}
102	          </select>
103	          <small>{isAdditionalApproval ? `${remainingEligible.length} of ${eligible.length} eligible datasets remain unapproved.` : 'Only datasets that pass every mandatory gate can be approved.'}</small>
104	          <button className="btn btn-primary" disabled={Boolean(busy) || !selectedApprovalCandidateId} onClick={() => onReview({ decision: 'APPROVE', candidateId: selectedApprovalCandidateId })}>{busy === 'APPROVE' ? 'Approving…' : 'Approve selected dataset'}</button>
105	        </div>}
106	        {!isAdditionalApproval && <div className="scout-refinement">
107	          <label htmlFor={`refinement-feedback-${run.runId}`}>{needsInput ? 'What should the scout search for next?' : 'What should the scout improve?'}</label>
108	          <textarea id={`refinement-feedback-${run.runId}`} rows={3} value={feedback} onChange={event => setFeedback(event.target.value)} placeholder="Example: prioritize datasets with free-motion baselines and CSV files" disabled={Boolean(busy) || !refinementAvailable} />
109	          <small>{refinementAvailable ? `${run.reviewIterationsUsed}/2 refinement searches used. Feedback is added to the next bounded query.` : hasRefinementSlot ? 'The Tavily credit budget is exhausted; start a new run to continue.' : 'The refinement limit is reached; start a new run to continue.'}</small>
110	          <button className="btn" disabled={Boolean(busy) || !refinementAvailable || normalizedFeedback.length < 3} onClick={() => onReview({ decision: 'REJECT', candidateId: needsInput ? undefined : selectedCandidateId || undefined, note: normalizedFeedback })}>{busy === 'REJECT' ? 'Refining…' : needsInput ? 'Refine search' : 'Reject and refine'}</button>
111	        </div>}
112	      </div>
113	      {run.reviewFeedback.length > 0 && <details className="scout-review-history"><summary>Applied reviewer feedback ({run.reviewFeedback.length})</summary><ol>{run.reviewFeedback.map((item, index) => <li key={`${index}-${item}`}>{item}</li>)}</ol></details>}
114	    </section>}
115	    {run.manifest && <Manifest manifest={run.manifest} onUseSource={onUseSource} />}
116	  </div>;
117	}
 35	  customRequirements: string[];
 36	};
 37	
 38	export type RequirementsPreview = { requirements: RequirementDefinition[] };
 39	
 40	export type ResearchRequirement = RequirementDefinition & {
 41	  status: 'VERIFIED' | 'MISSING' | 'CONFLICTING' | 'UNVERIFIED';
 42	  evidenceIds: string[];
 43	};
 44	
 45	export type DatasetCandidate = {
 46	  id: string;
 47	  name: string;
 48	  canonicalUrl: string;
 49	  sourceKind: 'ZENODO' | 'GITHUB' | 'HUGGING_FACE';
 50	  description: string;
 51	  revision: string | null;
 52	  relatedUrls: string[];
 53	  sourceRole?: 'DISCOVERY_LEAD' | 'DATASET_ARTIFACT';
 54	  discoveryDepth?: number;
 55	  discoveredFromCandidateId?: string | null;
 56	};
 57	
 58	export type DatasetProfile = {
 59	  candidateId: string;
 60	  name: string;
 61	  canonicalUrl: string;
 62	  sourceKinds: ('ZENODO' | 'GITHUB' | 'HUGGING_FACE')[];
 63	  revision: string | null;
 64	  licenseId: string | null;
 65	  fileCount: number | null;
 66	  totalSizeBytes: number | null;
 67	  fileExtensions: string[];
 68	  domains: string[];
 69	  labels: string[];
 70	  sampleRateHz: number | null;
 71	  channelCount: number | null;
 72	  hasTimeSeriesFiles: boolean;
 73	  schemaDocumented: boolean;
 74	  acquisitionFeasible: boolean;
 75	  isDatasetArtifact?: boolean;
145	  | { decision: 'APPROVE'; candidateId: string; note?: string }
146	  | { decision: 'REJECT'; candidateId?: string; note: string };
147	
148	export type RefinementOutcome = {
149	  iteration: number;
150	  feedback: string;
151	  query: string;
152	  outcome: 'RECOMMENDATION_CHANGED' | 'RECOMMENDATION_WITHHELD' | 'EVIDENCE_EXPANDED' | 'CANDIDATES_ADDED' | 'NO_CHANGE';
153	  rejectedCandidateId: string | null;
154	  previousRecommendedCandidateId: string | null;
155	  recommendedCandidateId: string | null;
156	  newCandidateIds: string[];
157	  newEvidenceIds: string[];
158	};
