 92	    {candidate && assessment && <CandidateSummary candidate={candidate} profile={profile} assessment={assessment} isRecommendation={selectedCandidateId === run.recommendedCandidateId} />}
 93	    {run.assessments.length > 0 && <DecisionEvidence run={run} candidateId={selectedCandidateId || undefined} />}
 94	    {showReviewPanel && <section className="scout-approval" aria-labelledby="scout-approval-title">
 95	      <div><strong id="scout-approval-title">{needsInput ? 'Help the scout continue' : isAdditionalApproval ? 'Approve another dataset' : 'Human decision required'}</strong><p>{needsInput ? 'No dataset passed the current contract. Direct the next bounded search with specific missing evidence, source types, or alternatives.' : isAdditionalApproval ? `${approvedIds.size} eligible dataset${approvedIds.size === 1 ? '' : 's'} approved from this run. Review and approve another candidate, or open the approved-source library when you are done.` : 'Approve any eligible dataset, or give the scout specific feedback for another bounded search.'}</p></div>
 96	      <div className={`scout-approval-grid${needsInput ? ' needs-input' : isAdditionalApproval ? ' additional-approval' : ''}`}>
 97	        {!needsInput && <div className="scout-approval-choice">
 98	          <label htmlFor={`approval-candidate-${run.runId}`}>Dataset to approve</label>
 99	          <select id={`approval-candidate-${run.runId}`} value={selectedApprovalCandidateId} onChange={event => setSelectedCandidateId(event.target.value)} disabled={Boolean(busy) || approvalOptions.length === 0}>
100	            {approvalOptions.length === 0 && <option value="">No eligible datasets</option>}
101	            {approvalOptions.map(item => <option key={item.candidateId} value={item.candidateId}>{run.candidates.find(candidateItem => candidateItem.id === item.candidateId)?.name ?? item.candidateId} — {candidateSuitabilityLabel(item)}{item.candidateId === run.recommendedCandidateId ? ' (agent recommendation)' : ''}</option>)}
102	          </select>
103	          <small>{isAdditionalApproval ? `${remainingEligible.length} of ${eligible.length} eligible datasets remain unapproved.` : 'Only datasets that pass every mandatory gate can be approved.'}</small>
104	          <button className="btn btn-primary" disabled={Boolean(busy) || !selectedApprovalCandidateId} onClick={() => onReview({ decision: 'APPROVE', candidateId: selectedApprovalCandidateId })}>{busy === 'APPROVE' ? 'Approving…' : 'Approve selected dataset'}</button>
105	        </div>}
106	        {!isAdditionalApproval && <div className="scout-refinement">
107	          <label htmlFor={`refinement-feedback-${run.runId}`}>{needsInput ? 'What should the scout search for next?' : 'What should the scout improve?'}</label>
108	          <textarea id={`refinement-feedback-${run.runId}`} rows={3} value={feedback} onChange={event => setFeedback(event.target.value)} placeholder="Example: prioritize datasets with free-motion baselines and CSV files" disabled={Boolean(busy) || !refinementAvailable} />
109	          <small>{refinementAvailable ? `${run.reviewIterationsUsed}/2 refinement searches used. Feedback is added to the next bounded query.` : hasRefinementSlot ? 'The Tavily credit budget is exhausted; start a new run to continue.' : 'The refinement limit is reached; start a new run to continue.'}</small>
110	          <button className="btn" disabled={Boolean(busy) || !refinementAvailable || normalizedFeedback.length < 3} onClick={() => onReview({ decision: 'REJECT', candidateId: needsInput ? undefined : selectedCandidateId || undefined, note: normalizedFeedback })}>{busy === 'REJECT' ? 'Refining…' : needsInput ? 'Refine search' : 'Reject and refine'}</button>
111	        </div>}
112	      </div>
113	      {run.reviewFeedback.length > 0 && <details className="scout-review-history"><summary>Applied reviewer feedback ({run.reviewFeedback.length})</summary><ol>{run.reviewFeedback.map((item, index) => <li key={`${index}-${item}`}>{item}</li>)}</ol></details>}
114	    </section>}
115	    {run.manifest && <Manifest manifest={run.manifest} onUseSource={onUseSource} />}
116	  </div>;
117	}
 35	  customRequirements: string[];
 36	};
